    init(cardId: String) { self.cardId = cardId; self.lastReviewDate = nil; self.interval = 0 }
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        cardId = try c.decode(String.self, forKey: .cardId)
        lastReviewDate = (try? c.decodeIfPresent(Date.self, forKey: .lastReviewDate)) ?? nil
