//
//  CloudAIService.swift
//  SwiftMandarin
//
//  URLSession-based client for cloud AI providers. Supports the OpenAI
//  chat-completions convention (OpenAI, DeepSeek, Doubao, Qwen/DashScope,
//  Kimi/Moonshot, Zhipu, MiniMax) and the Anthropic Messages convention
//  (Claude). Provides model listing, text chat, vision chat, and translation.
//
//  No third-party dependency — built directly on Foundation so any
//  OpenAI-compatible endpoint can be reached by configuring base URL + key.
//

import Foundation
import SwiftUI

// MARK: - Model Info

/// A provider-neutral model descriptor for the settings model picker.
struct CloudModelInfo: Identifiable, Hashable, Codable {
    let id: String
    var displayName: String { id }
}

// MARK: - Errors

enum CloudAIError: LocalizedError {
    case notCloudProvider
    case missingAPIKey(String)
    case invalidURL
    case requestEncodingFailed
    case httpError(Int, String)
    case emptyResponse
    case unexpectedResponse(String)

    var errorDescription: String? {
        switch self {
        case .notCloudProvider:
            return "Selected provider is not a cloud provider."
        case .missingAPIKey(let name):
            return "No API key configured for \(name). Add it in Settings → AI."
        case .invalidURL:
            return "The provider base URL is invalid."
        case .requestEncodingFailed:
            return "Failed to encode the request."
        case .httpError(let code, let body):
            let trimmed = body.count > 300 ? String(body.prefix(300)) + "…" : body
            return "Provider returned HTTP \(code): \(trimmed)"
        case .emptyResponse:
            return "The provider returned an empty response."
        case .unexpectedResponse(let detail):
            return "Unexpected response from provider: \(detail)"
        }
    }
}

// MARK: - Cloud AI Service

@Observable
@MainActor
final class CloudAIService {

    static let shared = CloudAIService()

    /// Per-provider live model lists (keyed by `AIProvider.rawValue`).
    private(set) var availableModels: [String: [CloudModelInfo]] = [:]

    /// Providers currently fetching their model list.
    private(set) var loadingProviders: Set<String> = []

    /// Last error message per provider (keyed by `AIProvider.rawValue`).
    private(set) var lastError: [String: String] = [:]

    private let session: URLSession = {
        let config = URLSessionConfiguration.default
        // Non-streamed responses arrive only after the model finishes, so large
        // structured/vision generations need a generous timeout.
        config.timeoutIntervalForRequest = 180
        config.timeoutIntervalForResource = 300
        config.waitsForConnectivity = true
        return URLSession(configuration: config)
    }()

    private init() {}

    // MARK: - Public State Accessors

    /// Models to show for a provider: live list if available, else curated defaults.
    func models(for provider: AIProvider) -> [CloudModelInfo] {
        if let live = availableModels[provider.rawValue], !live.isEmpty {
            return live
        }
        return provider.defaultModels.map { CloudModelInfo(id: $0) }
    }

    func isLoading(_ provider: AIProvider) -> Bool {
        loadingProviders.contains(provider.rawValue)
    }

    func error(for provider: AIProvider) -> String? {
        lastError[provider.rawValue]
    }

    // MARK: - Model Listing

    /// Fetch the available model list for a cloud provider via its API.
    /// Falls back to curated defaults when no listing endpoint exists or the
    /// request fails; never throws (errors are stored in `lastError`).
    func refreshModels(for provider: AIProvider) async {
        guard provider.isCloud else { return }
        let settings = AIModelSettings.shared
        let key = settings.apiKey(for: provider)

        lastError[provider.rawValue] = nil

        guard !key.isEmpty else {
            lastError[provider.rawValue] = CloudAIError.missingAPIKey(provider.displayName).localizedDescription
            return
        }

        // Providers without a standard listing endpoint use curated defaults.
        guard let modelsPath = settings.effectiveModelsPath(for: provider) else {
            availableModels[provider.rawValue] = provider.defaultModels.map { CloudModelInfo(id: $0) }
            return
        }

        guard let url = URL(string: settings.baseURL(for: provider) + modelsPath) else {
            lastError[provider.rawValue] = CloudAIError.invalidURL.localizedDescription
            return
        }

        loadingProviders.insert(provider.rawValue)
        defer { loadingProviders.remove(provider.rawValue) }

        var request = URLRequest(url: url)
        request.httpMethod = "GET"
        applyAuthHeaders(&request, provider: provider, key: key)

        do {
            let (data, response) = try await session.data(for: request)
            guard let http = response as? HTTPURLResponse else {
                throw CloudAIError.unexpectedResponse("No HTTP response")
            }
            guard (200...299).contains(http.statusCode) else {
                throw CloudAIError.httpError(http.statusCode, String(data: data, encoding: .utf8) ?? "")
            }
            let ids = Self.parseModelIDs(from: data)
            if ids.isEmpty {
                // Keep defaults visible if the endpoint returned nothing useful.
                availableModels[provider.rawValue] = provider.defaultModels.map { CloudModelInfo(id: $0) }
            } else {
                availableModels[provider.rawValue] = ids.map { CloudModelInfo(id: $0) }
            }
        } catch {
            lastError[provider.rawValue] = error.localizedDescription
            // Surface curated defaults so the picker remains usable.
            if availableModels[provider.rawValue] == nil {
                availableModels[provider.rawValue] = provider.defaultModels.map { CloudModelInfo(id: $0) }
            }
        }
    }

    /// Parse model IDs from common listing-response shapes.
    private static func parseModelIDs(from data: Data) -> [String] {
        guard let json = try? JSONSerialization.jsonObject(with: data) else { return [] }
        let container: [Any]?
        if let dict = json as? [String: Any] {
            container = (dict["data"] as? [Any]) ?? (dict["models"] as? [Any])
        } else {
            container = json as? [Any]
        }
        guard let items = container else { return [] }
        var ids: [String] = []
        for item in items {
            if let s = item as? String {
                ids.append(s)
            } else if let obj = item as? [String: Any] {
                // Skip retired models (e.g. Volcengine Ark marks them "Shutdown").
                if (obj["status"] as? String) == "Shutdown" { continue }
                if let id = obj["id"] as? String { ids.append(id) }
                else if let name = obj["name"] as? String { ids.append(name) }
            }
        }
        // Keep only chat/vision-capable LLMs; drop embeddings, rerankers,
        // image/video/audio/3D generators, OCR-only, captioners, etc.
        return ids.filter(isChatCapableModel).sorted()
    }

    /// Keywords that mark a model as NOT a conversational chat/vision LLM.
    private static let nonChatModelKeywords: [String] = [
        "embedding", "embed", "rerank", "bge", "gte", "gme",
        "tts", "asr", "audio", "cosyvoice", "sambert", "speech", "voice",
        "paraformer", "sensevoice", "whisper", "realtime",
        "wanx", "wan2", "flux", "seedream", "stable-diffusion", "sdxl",
        "cogview", "kolors", "image-synthesis", "image-generation", "image-edit",
        "text2image", "anytext", "virtualmodel", "facechain",
        "dall-e", "gpt-image", "qwen-image",
        "seedance", "video", "t2i", "t2v", "i2v", "svd",
        "seed3d", "hyper3d", "hitem", "captioner", "ocr",
    ]

    /// Whether a model id looks like a chat/vision-capable LLM (vs. a
    /// generation/embedding/audio model that this app can't use).
    static func isChatCapableModel(_ id: String) -> Bool {
        let lower = id.lowercased()
        return !nonChatModelKeywords.contains { lower.contains($0) }
    }

    // MARK: - Chat

    /// Send a chat request and return the assistant's text content.
    /// - Parameters:
    ///   - imageData: optional single image for vision-capable providers.
    ///   - images: optional multiple images (combined with `imageData`).
    ///   - jsonMode: request a JSON object response where supported.
    func chat(
        provider: AIProvider,
        model: String,
        system: String,
        user: String,
        imageData: Data? = nil,
        images: [Data] = [],
        jsonMode: Bool = false,
        maxTokens: Int = 4096
    ) async throws -> String {
        guard provider.isCloud else { throw CloudAIError.notCloudProvider }
        let settings = AIModelSettings.shared
        let key = settings.apiKey(for: provider)
        guard !key.isEmpty else { throw CloudAIError.missingAPIKey(provider.displayName) }

        let base = settings.baseURL(for: provider)
        let style = settings.effectiveAPIStyle(for: provider)
        guard let url = URL(string: base + settings.effectiveChatPath(for: provider)) else { throw CloudAIError.invalidURL }

        // Combine the convenience single image with the multi-image array;
        // only send images at all for vision-capable providers.
        let combinedImages = (imageData.map { [$0] } ?? []) + images
        let imagesToSend = provider.supportsVision ? combinedImages : []

        var request = URLRequest(url: url)
        request.httpMethod = "POST"
        applyAuthHeaders(&request, provider: provider, key: key)

        // Only request the strict JSON response_format where the provider
        // supports it; others still get JSON via the prompt + tolerant parsing.
        let useResponseFormat = jsonMode && provider.supportsJSONResponseFormat

        let body: [String: Any]
        switch style {
        case .openAICompatible:
            body = Self.openAIBody(
                model: model, system: system, user: user,
                images: imagesToSend,
                jsonMode: jsonMode, useResponseFormat: useResponseFormat, maxTokens: maxTokens
            )
        case .anthropic:
            body = Self.anthropicBody(
                model: model, system: system, user: user,
                images: imagesToSend, maxTokens: maxTokens
            )
        }

        guard let httpBody = try? JSONSerialization.data(withJSONObject: body) else {
            throw CloudAIError.requestEncodingFailed
        }
        request.httpBody = httpBody

        let (data, response) = try await session.data(for: request)
        guard let http = response as? HTTPURLResponse else {
            throw CloudAIError.unexpectedResponse("No HTTP response")
        }
        guard (200...299).contains(http.statusCode) else {
            throw CloudAIError.httpError(http.statusCode, String(data: data, encoding: .utf8) ?? "")
        }

        let content: String?
        switch style {
        case .openAICompatible: content = Self.parseOpenAIContent(from: data)
        case .anthropic: content = Self.parseAnthropicContent(from: data)
        }

        guard let text = content, !text.trimmingCharacters(in: .whitespacesAndNewlines).isEmpty else {
            throw CloudAIError.emptyResponse
        }
        return text
    }

    /// Translate text using a cloud provider.
    func translate(_ text: String, sourceIsChinese: Bool, provider: AIProvider, model: String) async throws -> String {
        let system = """
        You are an expert translator between English and Mandarin Chinese (Simplified).
        Translate accurately and naturally, preserving meaning, tone and register.
        For English→Chinese use 简体中文. Respond with ONLY the translation, no commentary.
        """
        let direction = sourceIsChinese ? "Chinese to English" : "English to Chinese"
        let user = "Translate the following from \(direction):\n\n\(text)"
        let result = try await chat(provider: provider, model: model, system: system, user: user, maxTokens: 2048)
        return result.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    // MARK: - Request Building

    private func applyAuthHeaders(_ request: inout URLRequest, provider: AIProvider, key: String) {
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        switch AIModelSettings.shared.effectiveAPIStyle(for: provider) {
        case .openAICompatible:
            request.setValue("Bearer \(key)", forHTTPHeaderField: "Authorization")
        case .anthropic:
            // Anthropic-style gateways accept x-api-key; also send Bearer so
            // proxies that expect either header authenticate.
            request.setValue(key, forHTTPHeaderField: "x-api-key")
            request.setValue("Bearer \(key)", forHTTPHeaderField: "Authorization")
            request.setValue("2023-06-01", forHTTPHeaderField: "anthropic-version")
        }
    }

    private static func openAIBody(
        model: String, system: String, user: String,
        images: [Data], jsonMode: Bool, useResponseFormat: Bool, maxTokens: Int
    ) -> [String: Any] {
        var systemPrompt = system
        var userContent: Any = user

        if jsonMode, !systemPrompt.lowercased().contains("json") {
            systemPrompt += "\n\nRespond with a single valid JSON object."
        }

        if !images.isEmpty {
            var parts: [[String: Any]] = [["type": "text", "text": user]]
            for image in images {
                let dataURL = "data:\(mediaType(for: image));base64,\(image.base64EncodedString())"
                parts.append(["type": "image_url", "image_url": ["url": dataURL]])
            }
            userContent = parts
        }

        var body: [String: Any] = [
            "model": model,
            "messages": [
                ["role": "system", "content": systemPrompt],
                ["role": "user", "content": userContent],
            ],
            "stream": false,
        ]

        // Reasoning families reject a custom `temperature`. The token-limit
        // parameter, however, is provider-specific: OpenAI's o-series uses
        // `max_completion_tokens`, while other OpenAI-compatible reasoners
        // (e.g. DeepSeek's `deepseek-reasoner`) still use the classic
        // `max_tokens`. Everything else keeps `max_tokens` + `temperature`.
        if isReasoningModel(model) {
            if isOpenAIReasoningModel(model) {
                body["max_completion_tokens"] = maxTokens
            } else {
                body["max_tokens"] = maxTokens
            }
        } else {
            body["temperature"] = 0.3
            body["max_tokens"] = maxTokens
        }

        if useResponseFormat {
            body["response_format"] = ["type": "json_object"]
        }
        return body
    }

    /// The bare model id with any provider prefix (e.g. "openai/", "openai:") stripped.
    private static func bareModelID(_ modelID: String) -> String {
        modelID.lowercased().split(whereSeparator: { $0 == "/" || $0 == ":" }).last.map(String.init)
            ?? modelID.lowercased()
    }

    /// OpenAI o-series reasoning models (o1, o3, o4, o5… plus -mini/-pro/-preview
    /// variants) — the only family that requires `max_completion_tokens`.
    private static func isOpenAIReasoningModel(_ modelID: String) -> Bool {
        let bare = bareModelID(modelID)
        guard let first = bare.first, first == "o",
              let second = bare.dropFirst().first, second.isNumber else { return false }
        return true
    }

    /// Any reasoning model that rejects a custom `temperature` — the OpenAI
    /// o-series plus "reasoner" families such as DeepSeek's `deepseek-reasoner`.
    private static func isReasoningModel(_ modelID: String) -> Bool {
        isOpenAIReasoningModel(modelID) || bareModelID(modelID).contains("reasoner")
    }

    private static func anthropicBody(
        model: String, system: String, user: String,
        images: [Data], maxTokens: Int
    ) -> [String: Any] {
        var userContent: [[String: Any]] = [["type": "text", "text": user]]
        for image in images {
            userContent.append([
                "type": "image",
                "source": [
                    "type": "base64",
                    "media_type": mediaType(for: image),
                    "data": image.base64EncodedString(),
                ],
            ])
        }
        return [
            "model": model,
            "max_tokens": maxTokens,
            "system": system,
            "messages": [["role": "user", "content": userContent]],
        ]
    }

    // MARK: - Response Parsing

    private static func parseOpenAIContent(from data: Data) -> String? {
        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return nil }
        guard let choices = json["choices"] as? [[String: Any]], let first = choices.first else { return nil }
        if let message = first["message"] as? [String: Any] {
            // content may be a string or an array of content parts.
            if let content = message["content"] as? String { return content }
            if let parts = message["content"] as? [[String: Any]] {
                return parts.compactMap { $0["text"] as? String }.joined()
            }
        }
        if let text = first["text"] as? String { return text }
        return nil
    }

    private static func parseAnthropicContent(from data: Data) -> String? {
        guard let json = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else { return nil }
        guard let content = json["content"] as? [[String: Any]] else { return nil }
        let texts = content.compactMap { block -> String? in
            (block["type"] as? String) == "text" ? block["text"] as? String : nil
        }
        return texts.isEmpty ? nil : texts.joined()
    }

    // MARK: - Media Type Detection

    private static func mediaType(for data: Data) -> String {
        guard let first = data.first else { return "image/jpeg" }
        switch first {
        case 0x89: return "image/png"
        case 0xFF: return "image/jpeg"
        case 0x47: return "image/gif"
        case 0x52: return "image/webp"
        default: return "image/jpeg"
        }
    }
}

//
//  OllamaService.swift
//  SwiftMandarin
//
//  Service for interacting with local Ollama models as an alternative to Apple Intelligence.
//  Provides model discovery, chat completion, and structured output generation.
//

import Foundation
import SwiftUI
import Ollama

// MARK: - Ollama Model Info

/// Represents an available Ollama model with its metadata
struct OllamaModelInfo: Identifiable, Hashable, Codable {
    var id: String { name }
    let name: String
    let size: Int64
    let parameterSize: String
    let family: String
    let supportsThinking: Bool
    let supportsTools: Bool

    /// Human-readable size string
    var sizeString: String {
        let formatter = ByteCountFormatter()
        formatter.countStyle = .file
        return formatter.string(fromByteCount: size)
    }
}

// MARK: - Ollama Service

/// Service that provides access to local Ollama models for AI-powered features
@Observable
@MainActor
final class OllamaService {

    static let shared = OllamaService()

    // MARK: - Properties

    /// The Ollama client instance
    private var client: Ollama.Client

    /// Available models discovered from Ollama
    private(set) var availableModels: [OllamaModelInfo] = []

    /// Whether Ollama server is reachable
    private(set) var isConnected: Bool = false

    /// Last connection error if any
    private(set) var connectionError: String?

    /// Whether we're currently loading models
    private(set) var isLoadingModels: Bool = false

    /// The Ollama server host URL
    var hostURL: URL {
        get { client.host }
        set { 
            client = Ollama.Client(host: newValue)
            // Re-check connection when host changes
            Task { await checkConnection() }
        }
    }

    // MARK: - Configuration

    /// Default options for gpt-oss 20b model with extended context and reasoning
    static let defaultOptions: [String: Ollama.Value] = [
        "num_ctx": .int(128000),           // 128k context window
        "temperature": .double(0.7),        // Balanced creativity
        "top_p": .double(0.9),              // Nucleus sampling
        "repeat_penalty": .double(1.1),     // Reduce repetition
        "num_predict": .int(-1),            // No limit on tokens
    ]

    /// Options optimized for reasoning tasks
    static let reasoningOptions: [String: Ollama.Value] = [
        "num_ctx": .int(128000),            // 128k context window
        "temperature": .double(0.3),         // More deterministic for reasoning
        "top_p": .double(0.95),
        "repeat_penalty": .double(1.05),
        "num_predict": .int(-1),
    ]

    // MARK: - Initialization

    private init() {
        // Initialize with default localhost
        self.client = Ollama.Client.default
    }

    // MARK: - Connection Management

    /// Check if Ollama server is reachable
    func checkConnection() async {
        do {
            _ = try await client.version()
            isConnected = true
            connectionError = nil
        } catch {
            isConnected = false
            connectionError = error.localizedDescription
        }
    }

    /// Refresh the list of available models from Ollama
    func refreshModels() async {
        isLoadingModels = true
        defer { isLoadingModels = false }

        do {
            let response = try await client.listModels()

            // Get detailed info for each model to check capabilities
            var models: [OllamaModelInfo] = []
            for model in response.models {
                // Skip any discovered model whose name isn't a valid Ollama model ID
                // rather than force-unwrapping (which would crash the whole refresh).
                guard let modelID = Ollama.Model.ID(rawValue: model.name) else {
                    continue
                }

                // Try to get capabilities for each model
                var supportsThinking = false
                var supportsTools = false

                do {
                    let details = try await client.showModel(modelID)
                    supportsThinking = details.capabilities.contains(.thinking)
                    supportsTools = details.capabilities.contains(.tools)
                } catch {
                    // Ignore errors fetching details, use defaults
                }

                let info = OllamaModelInfo(
                    name: model.name,
                    size: model.size,
                    parameterSize: model.details.parameterSize,
                    family: model.details.family,
                    supportsThinking: supportsThinking,
                    supportsTools: supportsTools
                )
                models.append(info)
            }

            availableModels = models.sorted { $0.name < $1.name }
            isConnected = true
            connectionError = nil
        } catch {
            availableModels = []
            isConnected = false
            connectionError = error.localizedDescription
        }
    }

    // MARK: - Chat Completion

    /// Generate a chat completion with the specified model
    /// - Parameters:
    ///   - model: The model name to use
    ///   - systemPrompt: System instructions for the model
    ///   - userPrompt: The user's message
    ///   - enableThinking: Whether to enable thinking/reasoning mode
    ///   - options: Additional model options
    /// - Returns: The model's response content
    func chat(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        enableThinking: Bool = true,
        options: [String: Ollama.Value]? = nil
    ) async throws -> (content: String, thinking: String?) {
        guard let modelID = Ollama.Model.ID(rawValue: model) else {
            throw OllamaServiceError.modelNotFound(model)
        }

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        let response = try await client.chat(
            model: modelID,
            messages: messages,
            options: options ?? Self.defaultOptions,
            think: enableThinking,
            keepAlive: .minutes(10)
        )

        return (content: response.message.content, thinking: response.message.thinking)
    }

    /// Generate a streaming chat completion
    func chatStream(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        enableThinking: Bool = true,
        options: [String: Ollama.Value]? = nil
    ) throws -> AsyncThrowingStream<Ollama.Client.ChatResponse, Error> {
        guard let modelID = Ollama.Model.ID(rawValue: model) else {
            throw OllamaServiceError.modelNotFound(model)
        }

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        return try client.chatStream(
            model: modelID,
            messages: messages,
            options: options ?? Self.defaultOptions,
            think: enableThinking,
            keepAlive: .minutes(10)
        )
    }

    // MARK: - Structured Output Generation

    /// Generate a structured JSON response matching a schema
    /// - Parameters:
    ///   - model: The model name to use
    ///   - systemPrompt: System instructions
    ///   - userPrompt: User message
    ///   - schema: JSON schema for the expected output
    ///   - enableThinking: Whether to enable thinking mode
    /// - Returns: The JSON string response
    func generateStructured(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        schema: Ollama.Value,
        enableThinking: Bool = true
    ) async throws -> String {
        guard let modelID = Ollama.Model.ID(rawValue: model) else {
            throw OllamaServiceError.modelNotFound(model)
        }

        let messages: [Ollama.Chat.Message] = [
            .system(systemPrompt),
            .user(userPrompt)
        ]

        let response = try await client.chat(
            model: modelID,
            messages: messages,
            options: Self.reasoningOptions,
            format: schema,
            think: enableThinking,
            keepAlive: .minutes(10)
        )

        return response.message.content
    }

    /// Generate structured output and decode it to a Codable type
    func generateAndDecode<T: Codable>(
        model: String,
        systemPrompt: String,
        userPrompt: String,
        type: T.Type,
        enableThinking: Bool = true
    ) async throws -> T {
        // Build JSON schema from type (simplified approach)
        let jsonString = try await generateStructured(
            model: model,
            systemPrompt: systemPrompt,
            userPrompt: userPrompt,
            schema: "json",
            enableThinking: enableThinking
        )

        guard let data = jsonString.data(using: .utf8) else {
            throw OllamaServiceError.invalidResponse("Response is not valid UTF-8")
        }

        do {
            return try JSONDecoder().decode(T.self, from: data)
        } catch {
            throw OllamaServiceError.decodingFailed("Failed to decode response: \(error.localizedDescription)")
        }
    }

    // MARK: - Translation

    /// Translate text using Ollama
    /// - Parameters:
    ///   - text: The text to translate
    ///   - sourceIsChinese: Whether the source is Chinese (true) or English (false)
    ///   - model: The model to use
    /// - Returns: The translated text
    func translate(
        _ text: String,
        sourceIsChinese: Bool,
        model: String
    ) async throws -> String {
        let systemPrompt = """
        You are an expert translator specializing in English and Mandarin Chinese (Simplified).

        Your translations should be:
        1. ACCURATE: Preserve the exact meaning and intent of the source text
        2. NATURAL: Use idiomatic expressions appropriate for the target language
        3. CONTEXTUAL: Consider the context and register (formal/informal)
        4. CULTURAL: Adapt cultural references when necessary for clarity

        For English to Chinese translations:
        - Use Simplified Chinese characters (简体中文)
        - Choose vocabulary appropriate for modern standard Mandarin (普通话)
        - Maintain the tone and style of the original

        For Chinese to English translations:
        - Use natural, fluent English
        - Preserve nuances and connotations where possible
        - Clarify ambiguous cultural references if needed

        Respond with ONLY the translation, no explanations or additional text.
        """

        let direction = sourceIsChinese ? "Chinese to English" : "English to Chinese"
        let userPrompt = """
        Translate the following text from \(direction):

        \(text)
        """

        let (content, _) = try await chat(
            model: model,
            systemPrompt: systemPrompt,
            userPrompt: userPrompt,
            enableThinking: false, // Translation doesn't need reasoning
            options: Self.defaultOptions
        )

        return content.trimmingCharacters(in: .whitespacesAndNewlines)
    }
}

// MARK: - Errors

enum OllamaServiceError: LocalizedError {
    case notConnected
    case modelNotFound(String)
    case invalidResponse(String)
    case decodingFailed(String)
    case generationFailed(String)

    var errorDescription: String? {
        switch self {
        case .notConnected:
            return "Ollama server is not connected. Please ensure Ollama is running."
        case .modelNotFound(let name):
            return "Model '\(name)' not found. Please pull the model first."
        case .invalidResponse(let detail):
            return "Invalid response from Ollama: \(detail)"
        case .decodingFailed(let detail):
            return "Failed to decode response: \(detail)"
        case .generationFailed(let detail):
            return "Generation failed: \(detail)"
        }
    }
}

//
//  AIModelSettings.swift
//  SwiftMandarin
//
//  Manages AI provider settings and preferences. Supports Apple Intelligence
//  (Foundation Models), local Ollama, and a family of cloud providers
//  (OpenAI, Anthropic/Claude, Deepseek, Doubao, Qwen, Kimi, Zhipu, Minimax)
//  reached over their REST APIs. API keys are stored in the Keychain.
//

import Foundation
import SwiftUI

// MARK: - Provider API Style

/// The request/response convention a cloud provider uses.
enum AIProviderAPIStyle {
    /// OpenAI `/chat/completions` + `/models`, `Authorization: Bearer` auth.
    case openAICompatible
    /// Anthropic `/v1/messages` + `/v1/models`, `x-api-key` + `anthropic-version`.
    case anthropic
}

// MARK: - AI Provider

/// The AI provider to use for AI-powered features.
enum AIProvider: String, CaseIterable, Identifiable, Codable {
    case appleIntelligence = "apple"
    case ollama = "ollama"
    case openAI = "openai"
    case anthropic = "anthropic"
    case deepseek = "deepseek"
    case doubao = "doubao"
    case qwen = "qwen"
    case kimi = "kimi"
    case zhipu = "zhipu"
    case minimax = "minimax"

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .appleIntelligence: return "Apple Intelligence"
        case .ollama: return "Ollama (Local)"
        case .openAI: return "OpenAI"
        case .anthropic: return "Claude (Anthropic)"
        case .deepseek: return "DeepSeek"
        case .doubao: return "Doubao 豆包"
        case .qwen: return "Qwen 通义千问"
        case .kimi: return "Kimi 月之暗面"
        case .zhipu: return "Zhipu GLM 智谱"
        case .minimax: return "MiniMax"
        }
    }

    var description: String {
        switch self {
        case .appleIntelligence: return "On-device AI powered by Apple's Foundation Models"
        case .ollama: return "Local AI models running via Ollama server"
        case .openAI: return "GPT models via the OpenAI API"
        case .anthropic: return "Claude models via the Anthropic API"
        case .deepseek: return "DeepSeek chat & reasoning models"
        case .doubao: return "ByteDance Doubao models via Volcengine Ark"
        case .qwen: return "Alibaba Qwen models via DashScope"
        case .kimi: return "Moonshot Kimi models"
        case .zhipu: return "Zhipu GLM models"
        case .minimax: return "MiniMax abab models"
        }
    }

    /// SF Symbol fallback, used only if the brand asset is unavailable.
    var iconName: String {
        switch self {
        case .appleIntelligence: return "apple.logo"
        case .ollama: return "server.rack"
        case .openAI: return "sparkles"
        case .anthropic: return "a.circle"
        case .deepseek: return "magnifyingglass.circle"
        case .doubao: return "cloud"
        case .qwen: return "cloud.sun"
        case .kimi: return "moon.stars"
        case .zhipu: return "brain"
        case .minimax: return "bolt.horizontal.circle"
        }
    }

    /// Name of the brand image in `Assets.xcassets` (vector SVG). Render via
    /// the shared `ProviderIcon` view, which falls back to `iconName` when the
    /// asset is missing.
    var brandAssetName: String { "brand-\(rawValue)" }

    /// Whether the brand asset is a single-color glyph that should be tinted to
    /// the surrounding foreground color (so it adapts to light/dark mode).
    /// Full-color brand marks render in their original colors instead.
    var brandAssetIsMonochrome: Bool {
        switch self {
        case .appleIntelligence, .openAI, .ollama: return true
        default: return false
        }
    }

    /// Whether this provider is a remote cloud API requiring an API key.
    var isCloud: Bool {
        switch self {
        case .appleIntelligence, .ollama: return false
        default: return true
        }
    }

    /// Whether this provider can accept image input for vision-based tasks.
    var supportsVision: Bool {
        switch self {
        case .openAI, .anthropic, .doubao, .qwen, .kimi, .zhipu: return true
        case .appleIntelligence, .ollama, .deepseek, .minimax: return false
        }
    }

    /// Whether the OpenAI-style `response_format: {type: json_object}` is
    /// supported. Providers without it still receive the JSON schema in the
    /// prompt and are parsed with tolerant extraction.
    var supportsJSONResponseFormat: Bool {
        switch self {
        case .openAI, .deepseek, .qwen: return true
        // Kimi's coding-plan endpoint rejects the `response_format` field
        // (returns 401), so JSON is requested via the prompt + tolerant parsing.
        case .anthropic, .doubao, .zhipu, .minimax, .kimi, .appleIntelligence, .ollama: return false
        }
    }

    // MARK: Cloud REST metadata (only meaningful when `isCloud`)

    var apiStyle: AIProviderAPIStyle {
        switch self {
        case .anthropic: return .anthropic
        default: return .openAICompatible
        }
    }

    /// Default base URL (without a trailing slash). Paths below are appended.
    ///
    /// Cloud providers default to their mainland-China (domestic) endpoints;
    /// users outside China can override with the international host in Settings
    /// (e.g. Qwen → dashscope-intl…, MiniMax → api.minimax.io, GLM → api.z.ai).
    var defaultBaseURL: String {
        switch self {
        case .openAI: return "https://api.openai.com/v1"
        case .anthropic: return "https://api.anthropic.com"
        case .deepseek: return "https://api.deepseek.com/v1"
        case .doubao: return "https://ark.cn-beijing.volces.com/api/v3"
        // Mainland-China DashScope (百炼). International users override with
        // https://dashscope-intl.aliyuncs.com/compatible-mode/v1
        case .qwen: return "https://dashscope.aliyuncs.com/compatible-mode/v1"
        // Kimi coding-plan endpoint (OpenAI-compatible). For the Anthropic
        // format set the base to https://api.kimi.com/coding and API Format
        // to Anthropic (path becomes …/coding/v1/messages).
        case .kimi: return "https://api.kimi.com/coding/v1"
        case .zhipu: return "https://open.bigmodel.cn/api/paas/v4"
        // MiniMax mainland-China host. International users override with
        // https://api.minimax.io/v1
        case .minimax: return "https://api.minimaxi.com/v1"
        case .appleIntelligence, .ollama: return ""
        }
    }

    /// Chat-completion path appended to the base URL.
    var chatPath: String {
        switch self {
        case .anthropic: return "/v1/messages"
        default: return "/chat/completions"
        }
    }

    /// Model-list path appended to the base URL, or `nil` when the provider
    /// has no standard listing endpoint (defaults are used instead).
    /// Every cloud provider here exposes an OpenAI-style `GET /models` (or the
    /// Anthropic `/v1/models`), so model lists are pulled live rather than
    /// relying on the curated `defaultModels` fallbacks.
    var modelsPath: String? {
        switch self {
        case .anthropic: return "/v1/models"
        case .openAI, .deepseek, .qwen, .doubao, .zhipu, .minimax: return "/models"
        // The Kimi coding-plan proxy exposes only the fixed `kimi-for-coding`
        // model and has no `GET /models` route — listing it returns 401, so we
        // skip live listing and use the curated default instead.
        case .kimi: return nil
        case .appleIntelligence, .ollama: return nil
        }
    }

    /// Curated fallback model IDs shown when live listing is unavailable.
    /// These are only a starting hint — use "Refresh Models" to pull the
    /// provider's current list from its API.
    var defaultModels: [String] {
        switch self {
        case .openAI:
            return ["gpt-4o", "gpt-4.1", "gpt-4.1-mini", "o4-mini", "o3", "gpt-4o-mini"]
        case .anthropic:
            // Newest first — the first entry doubles as the default selection.
            return ["claude-sonnet-4-6", "claude-opus-4-8", "claude-haiku-4-5", "claude-sonnet-4-5", "claude-opus-4-1"]
        case .deepseek:
            return ["deepseek-chat", "deepseek-reasoner"]
        case .doubao:
            // Ark model IDs use dashes + a date suffix (NOT dots), and must be
            // activated in the Ark Console (or use an inference endpoint ID, ep-…).
            return ["doubao-seed-1-6-250615", "doubao-1-5-pro-32k-250115", "doubao-1-5-vision-pro-32k-250115", "doubao-seed-1-6-flash-250828", "doubao-1-5-lite-32k-250115"]
        case .qwen:
            return ["qwen-plus", "qwen-max", "qwen-turbo", "qwen-vl-max", "qwen-vl-plus", "qwen-max-latest"]
        case .kimi:
            // The coding-plan endpoint (api.kimi.com/coding/v1) serves a single
            // unified model id. Users on the Moonshot Open Platform can override
            // the Base URL and type a kimi-k2.x / kimi-latest model id instead.
            return ["kimi-for-coding"]
        case .zhipu:
            return ["glm-4.6", "glm-4.5", "glm-4-plus", "glm-4.5v", "glm-4v-plus", "glm-4-flash"]
        case .minimax:
            return ["MiniMax-M2.5", "MiniMax-M2.7", "MiniMax-M3", "MiniMax-Text-01"]
        case .appleIntelligence, .ollama:
            return []
        }
    }

    /// A known vision-capable model id for this provider, used when an image
    /// task (grading, photo cleanup) needs vision but the user's selected model
    /// is text-only.
    var defaultVisionModel: String? {
        switch self {
        case .openAI: return "gpt-4o"
        case .anthropic: return "claude-sonnet-4-6"
        case .qwen: return "qwen-vl-max"
        case .doubao: return "doubao-1-5-vision-pro-32k-250115"
        case .zhipu: return "glm-4.5v"
        case .kimi: return "kimi-for-coding"
        case .deepseek, .minimax, .appleIntelligence, .ollama: return nil
        }
    }

    /// Keychain account name for this provider's API key.
    var keychainAccount: String { "apikey.\(rawValue)" }

    /// URL to obtain an API key, for the settings help link.
    var apiKeyURL: String? {
        switch self {
        case .openAI: return "https://platform.openai.com/api-keys"
        case .anthropic: return "https://console.anthropic.com/settings/keys"
        case .deepseek: return "https://platform.deepseek.com/api_keys"
        case .doubao: return "https://console.volcengine.com/ark"
        case .qwen: return "https://dashscope.console.aliyun.com/apiKey"
        // Kimi *Code* console — the coding-plan key. NOT the Moonshot Open
        // Platform (platform.kimi.ai); their keys are not interchangeable.
        case .kimi: return "https://www.kimi.com/code/console"
        case .zhipu: return "https://open.bigmodel.cn/usercenter/apikeys"
        case .minimax: return "https://platform.minimaxi.com/user-center/basic-information/interface-key"
        case .appleIntelligence, .ollama: return nil
        }
    }
}

// MARK: - AI Model Settings

/// Observable settings for AI model configuration.
@Observable
@MainActor
final class AIModelSettings {

    static let shared = AIModelSettings()

    // MARK: - UserDefaults Keys

    private enum Keys {
        static let provider = "ai_provider"
        static let ollamaModel = "ollama_model"
        static let ollamaHost = "ollama_host"
        static let enableThinking = "ollama_enable_thinking"
        static let contextLength = "ollama_context_length"
        static let cloudModels = "cloud_model_selections"   // [providerRaw: modelID]
        static let cloudBaseURLs = "cloud_base_overrides"   // [providerRaw: baseURL]
        static let cloudAPIStyles = "cloud_api_style_overrides" // [providerRaw: "openai"|"anthropic"]
        static let aiPhotoCleanup = "ai_photo_cleanup_enabled"
        static let batchConcurrency = "ai_batch_concurrency"
    }

    /// Allowed range for batch-analysis parallelism. Capped low enough that a
    /// cloud provider's rate limits aren't trivially tripped, but high enough
    /// to meaningfully speed up large lists.
    static let batchConcurrencyRange = 1...10

    // MARK: - Properties

    /// The currently selected AI provider.
    var provider: AIProvider {
        didSet { UserDefaults.standard.set(provider.rawValue, forKey: Keys.provider) }
    }

    /// The selected Ollama model name.
    var ollamaModel: String {
        didSet { UserDefaults.standard.set(ollamaModel, forKey: Keys.ollamaModel) }
    }

    /// The Ollama server host URL.
    var ollamaHost: String {
        didSet {
            UserDefaults.standard.set(ollamaHost, forKey: Keys.ollamaHost)
            updateOllamaServiceHost()
        }
    }

    /// Whether to enable thinking/reasoning mode for Ollama models.
    var enableThinking: Bool {
        didSet { UserDefaults.standard.set(enableThinking, forKey: Keys.enableThinking) }
    }

    /// Context length for Ollama models (in tokens).
    var contextLength: Int {
        didSet { UserDefaults.standard.set(contextLength, forKey: Keys.contextLength) }
    }

    /// When enabled, uploaded photos are passed through the selected AI
    /// provider for OCR cleanup/structuring before downstream processing.
    var aiPhotoCleanupEnabled: Bool {
        didSet { UserDefaults.standard.set(aiPhotoCleanupEnabled, forKey: Keys.aiPhotoCleanup) }
    }

    /// How many words the batch AI word-analysis processes in parallel. Clamped
    /// to `batchConcurrencyRange` on write so a corrupted/out-of-range value can
    /// never reach the task group.
    var batchConcurrency: Int {
        didSet {
            let clamped = min(max(batchConcurrency, Self.batchConcurrencyRange.lowerBound),
                              Self.batchConcurrencyRange.upperBound)
            if clamped != batchConcurrency {
                batchConcurrency = clamped
                return  // the re-assignment re-enters didSet and persists the clamped value
            }
            UserDefaults.standard.set(batchConcurrency, forKey: Keys.batchConcurrency)
        }
    }

    /// Per-provider selected cloud model IDs.
    private(set) var cloudModelSelections: [String: String] {
        didSet { persistDictionary(cloudModelSelections, key: Keys.cloudModels) }
    }

    /// Per-provider base URL overrides (empty entry → use provider default).
    private(set) var cloudBaseURLOverrides: [String: String] {
        didSet { persistDictionary(cloudBaseURLOverrides, key: Keys.cloudBaseURLs) }
    }

    /// Per-provider API-format overrides ("openai" / "anthropic"). When absent,
    /// the provider's built-in style is used. Lets users point a provider at an
    /// Anthropic-compatible gateway (e.g. a Kimi "coding" endpoint).
    private(set) var apiStyleOverrides: [String: String] {
        didSet { persistDictionary(apiStyleOverrides, key: Keys.cloudAPIStyles) }
    }

    /// In-memory mirror of Keychain API keys so SwiftUI reacts to changes.
    /// Loaded from the Keychain at init; writes go through to the Keychain.
    private(set) var apiKeys: [String: String] = [:]

    // MARK: - Initialization

    private init() {
        let savedProvider = UserDefaults.standard.string(forKey: Keys.provider) ?? AIProvider.appleIntelligence.rawValue
        self.provider = AIProvider(rawValue: savedProvider) ?? .appleIntelligence

        self.ollamaModel = UserDefaults.standard.string(forKey: Keys.ollamaModel) ?? "gpt-oss:20b"
        self.ollamaHost = UserDefaults.standard.string(forKey: Keys.ollamaHost) ?? "http://localhost:11434"
        self.enableThinking = UserDefaults.standard.object(forKey: Keys.enableThinking) as? Bool ?? true
        self.contextLength = UserDefaults.standard.object(forKey: Keys.contextLength) as? Int ?? 128000
        self.aiPhotoCleanupEnabled = UserDefaults.standard.object(forKey: Keys.aiPhotoCleanup) as? Bool ?? false

        // Default 3 — a safe parallelism that speeds up large lists without
        // tripping typical cloud rate limits. Clamp the persisted value in case
        // it was written by a future build with a wider range. (didSet does not
        // fire for this in-init assignment, so clamp here explicitly.)
        let savedConcurrency = UserDefaults.standard.object(forKey: Keys.batchConcurrency) as? Int ?? 3
        self.batchConcurrency = min(max(savedConcurrency, AIModelSettings.batchConcurrencyRange.lowerBound),
                                    AIModelSettings.batchConcurrencyRange.upperBound)

        self.cloudModelSelections = AIModelSettings.loadDictionary(key: Keys.cloudModels)
        self.cloudBaseURLOverrides = AIModelSettings.loadDictionary(key: Keys.cloudBaseURLs)
        self.apiStyleOverrides = AIModelSettings.loadDictionary(key: Keys.cloudAPIStyles)

        // Load API keys from Keychain into the observable mirror.
        var keys: [String: String] = [:]
        for p in AIProvider.allCases where p.isCloud {
            if let value = KeychainHelper.get(account: p.keychainAccount), !value.isEmpty {
                keys[p.rawValue] = value
            }
        }
        self.apiKeys = keys

        updateOllamaServiceHost()
    }

    // MARK: - Per-Provider Accessors

    /// The API key for a cloud provider (empty string when none).
    func apiKey(for provider: AIProvider) -> String {
        apiKeys[provider.rawValue] ?? ""
    }

    /// Store or clear a cloud provider's API key (Keychain + observable mirror).
    func setAPIKey(_ value: String, for provider: AIProvider) {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        KeychainHelper.set(trimmed, account: provider.keychainAccount)
        if trimmed.isEmpty {
            apiKeys.removeValue(forKey: provider.rawValue)
        } else {
            apiKeys[provider.rawValue] = trimmed
        }
    }

    /// The effective base URL for a cloud provider (override or default).
    func baseURL(for provider: AIProvider) -> String {
        let override = cloudBaseURLOverrides[provider.rawValue]?.trimmingCharacters(in: .whitespacesAndNewlines)
        if let override, !override.isEmpty { return override }
        return provider.defaultBaseURL
    }

    func setBaseURLOverride(_ value: String, for provider: AIProvider) {
        let trimmed = value.trimmingCharacters(in: .whitespacesAndNewlines)
        if trimmed.isEmpty || trimmed == provider.defaultBaseURL {
            cloudBaseURLOverrides.removeValue(forKey: provider.rawValue)
        } else {
            cloudBaseURLOverrides[provider.rawValue] = trimmed
        }
    }

    /// The API-format override for a provider, or nil when using its default.
    func apiStyleOverride(for provider: AIProvider) -> AIProviderAPIStyle? {
        switch apiStyleOverrides[provider.rawValue] {
        case "anthropic": return .anthropic
        case "openai": return .openAICompatible
        default: return nil
        }
    }

    func setAPIStyleOverride(_ style: AIProviderAPIStyle?, for provider: AIProvider) {
        switch style {
        case .anthropic: apiStyleOverrides[provider.rawValue] = "anthropic"
        case .openAICompatible: apiStyleOverrides[provider.rawValue] = "openai"
        case nil: apiStyleOverrides.removeValue(forKey: provider.rawValue)
        }
    }

    /// The effective API style for a provider (override or built-in default).
    func effectiveAPIStyle(for provider: AIProvider) -> AIProviderAPIStyle {
        apiStyleOverride(for: provider) ?? provider.apiStyle
    }

    /// Chat path derived from the effective API style.
    func effectiveChatPath(for provider: AIProvider) -> String {
        switch effectiveAPIStyle(for: provider) {
        case .anthropic: return "/v1/messages"
        case .openAICompatible: return "/chat/completions"
        }
    }

    /// Models-list path derived from the effective API style.
    func effectiveModelsPath(for provider: AIProvider) -> String? {
        switch effectiveAPIStyle(for: provider) {
        case .anthropic: return "/v1/models"
        case .openAICompatible: return provider.modelsPath
        }
    }

    /// Heuristic: does this model id look vision-capable (accepts images)?
    static func isLikelyVisionModel(_ id: String) -> Bool {
        let l = id.lowercased()
        if ["vl", "vision", "omni", "qvq", "4v", "glm-4.5v", "pixtral", "llava", "internvl", "minicpm-v", "gemini"]
            .contains(where: { l.contains($0) }) { return true }
        // Providers whose flagship chat models are multimodal.
        if l.hasPrefix("claude-") || l.contains("gpt-4o") || l.contains("gpt-4.1") || l.hasPrefix("o4") || l.hasPrefix("o3") { return true }
        // Doubao multimodal "seed"/vision families.
        if l.contains("seed-1-6") || l.contains("seed-1-8") || l.contains("seed-2-") || l.contains("1-5-vision") { return true }
        return false
    }

    /// Resolve a vision-capable model for image tasks: the user's selected model
    /// if it's vision-capable, otherwise a vision model from the live list, then
    /// the provider's curated default vision model.
    func visionModel(for provider: AIProvider) -> String? {
        let selected = selectedModel(for: provider)
        // Respect the user's selection if it's already a vision model.
        if Self.isLikelyVisionModel(selected) { return selected }
        // Otherwise prefer the provider's known-good vision model.
        if let curated = provider.defaultVisionModel { return curated }
        // Last resort: any vision-looking model from the live list.
        return CloudAIService.shared.models(for: provider).map(\.id).first(where: Self.isLikelyVisionModel)
    }

    /// The selected model for a provider. Ollama maps to `ollamaModel`;
    /// cloud providers use their per-provider selection (or first default).
    func selectedModel(for provider: AIProvider) -> String {
        switch provider {
        case .ollama:
            return ollamaModel
        case .appleIntelligence:
            return ""
        default:
            if let chosen = cloudModelSelections[provider.rawValue], !chosen.isEmpty {
                return chosen
            }
            return provider.defaultModels.first ?? ""
        }
    }

    func setSelectedModel(_ model: String, for provider: AIProvider) {
        switch provider {
        case .ollama:
            ollamaModel = model
        case .appleIntelligence:
            break
        default:
            cloudModelSelections[provider.rawValue] = model
        }
    }

    // MARK: - Availability

    /// Whether Apple Intelligence is available.
    var isAppleIntelligenceAvailable: Bool {
        #if canImport(FoundationModels)
        return AIWordExplanationService.shared.isAvailable
        #else
        return false
        #endif
    }

    /// Whether a given provider is usable right now.
    func isAvailable(_ provider: AIProvider) -> Bool {
        switch provider {
        case .appleIntelligence:
            return isAppleIntelligenceAvailable
        case .ollama:
            return OllamaService.shared.isConnected
        default:
            return !apiKey(for: provider).isEmpty
        }
    }

    /// Whether any provider is available for AI features.
    var isAnyProviderAvailable: Bool {
        AIProvider.allCases.contains { isAvailable($0) }
    }

    /// Current effective provider — the selected one if usable, otherwise the
    /// first available provider, otherwise the selected one (so errors surface).
    var effectiveProvider: AIProvider {
        if isAvailable(provider) { return provider }
        return AIProvider.allCases.first { isAvailable($0) } ?? provider
    }

    /// Whether Ollama is selected and available.
    var isOllamaActive: Bool {
        provider == .ollama && OllamaService.shared.isConnected
    }

    /// Status message for the current configuration.
    var statusMessage: String {
        switch provider {
        case .appleIntelligence:
            return isAppleIntelligenceAvailable
                ? "Apple Intelligence is ready"
                : (AIWordExplanationService.shared.unavailabilityReason ?? "Apple Intelligence is not available")
        case .ollama:
            if OllamaService.shared.isConnected {
                return ollamaModel.isEmpty ? "Connected — select a model" : "Connected to \(ollamaModel)"
            }
            return OllamaService.shared.connectionError ?? "Not connected to Ollama"
        default:
            if apiKey(for: provider).isEmpty {
                return "Add your \(provider.displayName) API key"
            }
            let model = selectedModel(for: provider)
            return model.isEmpty ? "Ready — select a model" : "Using \(model)"
        }
    }

    /// Options dictionary for Ollama requests based on current settings.
    var ollamaOptions: [String: Ollama.Value] {
        [
            "num_ctx": .int(contextLength),
            "temperature": .double(0.7),
            "top_p": .double(0.9),
            "repeat_penalty": .double(1.1),
            "num_predict": .int(-1),
        ]
    }

    // MARK: - Methods

    private func updateOllamaServiceHost() {
        if let url = URL(string: ollamaHost) {
            OllamaService.shared.hostURL = url
        }
    }

    /// Refresh connection and available models for the active provider.
    func refreshConnection() async {
        switch provider {
        case .ollama:
            await OllamaService.shared.checkConnection()
            if OllamaService.shared.isConnected {
                await OllamaService.shared.refreshModels()
            }
        default:
            if provider.isCloud {
                await CloudAIService.shared.refreshModels(for: provider)
            }
        }
    }

    /// Select the first available Ollama model if none is selected.
    func selectDefaultModelIfNeeded() {
        if ollamaModel.isEmpty, let firstModel = OllamaService.shared.availableModels.first {
            ollamaModel = firstModel.name
        }
    }

    /// Reset to default settings.
    func resetToDefaults() {
        provider = .appleIntelligence
        ollamaModel = "gpt-oss:20b"
        ollamaHost = "http://localhost:11434"
        enableThinking = true
        contextLength = 128000
        aiPhotoCleanupEnabled = false
    }

    // MARK: - Persistence Helpers

    private func persistDictionary(_ dict: [String: String], key: String) {
        if let data = try? JSONEncoder().encode(dict) {
            UserDefaults.standard.set(data, forKey: key)
        }
    }

    private static func loadDictionary(key: String) -> [String: String] {
        guard let data = UserDefaults.standard.data(forKey: key),
              let dict = try? JSONDecoder().decode([String: String].self, from: data) else {
            return [:]
        }
        return dict
    }
}

