                            triggerTranslation()
                        }
                    }
                } label: {
                    Label("Paste", systemImage: "doc.on.clipboard")
                }
                .buttonStyle(.bordered)
                .controlSize(.small)

                // Microphone button for live speech translation
                Button {
                    isInputFocused = false
                    showLiveSpeechTranslation = true
                } label: {
                    Image(systemName: "mic.fill")
