        ScrollView {
            VStack(alignment: .leading, spacing: 16) {
                // Show English first if the source was Chinese (CN→EN scenario)
                if showEnglishFirst {
                    VStack(alignment: .leading, spacing: 8) {
                        Text("ENGLISH")
