                    }
                }

                // Show English below if it wasn't shown above
                if !showEnglishFirst {
                    Divider()

                    VStack(alignment: .leading, spacing: 8) {
                        Text("ENGLISH")
                            .font(.caption)
                            .fontWeight(.semibold)
                            .foregroundStyle(.secondary)

                        Text(detectedEnglishText)
