func chat(
    provider: AIProvider,
    model: String,
    system: String,
    user: String,
    imageData: Data? = nil,
    images: [Data] = [],
    jsonMode: Bool = false,
    maxTokens: Int = 4096
) async throws -> String {
    guard provider.isCloud else { throw CloudAIError.notCloudProvider }
    let settings = AIModelSettings.shared
    let key = settings.apiKey(for: provider)
    guard !key.isEmpty else { throw CloudAIError.missingAPIKey(provider.displayName) }

    let base = settings.baseURL(for: provider)
    let style = settings.effectiveAPIStyle(for: provider)
    guard let url = URL(string: base + settings.effectiveChatPath(for: provider)) else { throw CloudAIError.invalidURL }

    // Combine the convenience single image with the multi-image array;
    // only send images at all for vision-capable providers.
    let combinedImages = (imageData.map { [$0] } ?? []) + images
    let imagesToSend = provider.supportsVision ? combinedImages : []

    var request = URLRequest(url: url)
    request.httpMethod = "POST"
    applyAuthHeaders(&request, provider: provider, key: key)

    // Only request the strict JSON response_format where the provider
    // supports it; others still get JSON via the prompt + tolerant parsing.
    let useResponseFormat = jsonMode && provider.supportsJSONResponseFormat

    let body: [String: Any]
    switch style {
    case .openAICompatible:
        body = Self.openAIBody(
            model: model, system: system, user: user,
            images: imagesToSend,
            jsonMode: jsonMode, useResponseFormat: useResponseFormat, maxTokens: maxTokens
        )
    case .anthropic:
        body = Self.anthropicBody(
            model: model, system: system, user: user,
            images: imagesToSend, maxTokens: maxTokens
        )
    }

    guard let httpBody = try? JSONSerialization.data(withJSONObject: body) else {
        throw CloudAIError.requestEncodingFailed
    }
    request.httpBody = httpBody

    let (data, response) = try await session.data(for: request)
    guard let http = response as? HTTPURLResponse else {
        throw CloudAIError.unexpectedResponse("No HTTP response")
    }
    guard (200...299).contains(http.statusCode) else {
        throw CloudAIError.httpError(http.statusCode, String(data: data, encoding: .utf8) ?? "")
    }

struct ExtractedVocabItem: Codable, Identifiable, Hashable {
    var id: String { term }
    let term: String       // word/phrase in the source language
    let reading: String    // pinyin / pronunciation hint
    let meaning: String    // translation/definition in the other language

    init(term: String, reading: String, meaning: String) {
        self.term = term; self.reading = reading; self.meaning = meaning
    }

    // Tolerate models that omit `reading`/`meaning`.
    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        term = try c.decode(String.self, forKey: .term)
        reading = (try? c.decode(String.self, forKey: .reading)) ?? ""
        meaning = (try? c.decode(String.self, forKey: .meaning)) ?? ""
    }
}

/// Wrapper matching the `{"items":[…]}` JSON shape models return.
struct ExtractedVocabResponse: Codable {
    let items: [ExtractedVocabItem]
}

// MARK: - Workbook Grading (structured output)

/// One graded question returned by the grading model.
struct GradedQuestion: Identifiable, Decodable {
    let id = UUID()
    let questionNumber: String
    let question: String
    let studentAnswer: String
    let correctAnswer: String
    let isCorrect: Bool
    let explanation: String
    /// The complete sentence in the LEARNING language (e.g. a fill-in-the-blank
    /// with the correct word filled in), for read-aloud pronunciation practice.
    let fullSentence: String
    /// Study item for a wrong answer (optional).
    let vocab: ExtractedVocabItem?

    enum CodingKeys: String, CodingKey {
        case questionNumber, question, studentAnswer, correctAnswer, isCorrect, explanation, fullSentence, vocab
    }

